import { ChangeDetectionStrategy, Component, computed, signal } from '@angular/core';
import { CurrencyPipe } from '@angular/common';

interface Product {
  id: string;
  name: string;
  price: number;
}

interface CartItem extends Product {
  quantity: number;
}

const PRODUCTS: Product[] = [
  { id: 'p1', name: 'Wireless Headphones', price: 129.99 },
  { id: 'p2', name: 'Mechanical Keyboard', price: 89.5 },
  { id: 'p3', name: 'Ergonomic Mouse', price: 49.99 },
  { id: 'p4', name: 'USB-C Hub', price: 39.0 }
];

@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [CurrencyPipe],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  readonly products = PRODUCTS;
  readonly cartItems = signal<CartItem[]>([]);

  readonly totalQty = computed(() => this.cartItems().reduce((sum, item) => sum + item.quantity, 0));
  readonly totalPrice = computed(() =>
    this.cartItems().reduce((sum, item) => sum + item.price * item.quantity, 0)
  );

  addToCart(product: Product): void {
    const inCart = this.cartItems().some((item) => item.id === product.id);
    if (inCart) {
      this.changeQuantity(product.id, 1);
    } else {
      this.cartItems.update((items) => [...items, { ...product, quantity: 1 }]);
    }
  }

  increaseQty(item: CartItem): void {
    this.changeQuantity(item.id, 1);
  }

  decreaseQty(item: CartItem): void {
    if (item.quantity <= 1) {
      this.removeItem(item);
      return;
    }

    this.changeQuantity(item.id, -1);
  }

  removeItem(item: CartItem): void {
    this.cartItems.update((items) => items.filter((line) => line.id !== item.id));
  }

  // A new array with a copied line: changing item.quantity in place would not notify the signal,
  // and totalQty and totalPrice would keep their old results.
  private changeQuantity(id: string, delta: number): void {
    this.cartItems.update((items) =>
      items.map((line) => (line.id === id ? { ...line, quantity: line.quantity + delta } : line))
    );
  }
}
